# minimal helpers so the shared check scripts run on GitHub (generated by scripts/seed-pipeline.sh)
CODE_DIR="${CODE_DIR:-$PWD}"
info() { printf '==> %s\n' "$*"; }
ok()   { printf 'OK  %s\n' "$*"; }
warn() { printf '!   %s\n' "$*" >&2; }
die()  { printf 'FAIL %s\n' "$*" >&2; exit 1; }
require_project() { :; }
